quota_scripts.script:
function httpErr(e) {
  var m = e && e.message ? String(e.message) : String(e);
  if (m.indexOf("HTTP ") === 0) return m;
  if (m.indexOf("JSON parse: ") === 0) return "Parse: " + m.slice(12);
  return "Network: " + m;
}
function num(v) {
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.trim() !== "" && !isNaN(Number(v))) return Number(v);
  return 0.0;
}
function parseNum(v) {
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.trim() !== "" && !isNaN(Number(v))) return Number(v);
  return null;
}
if (ctx.apiKey == null || ctx.apiKey.trim() === "") {
  return { success: false, error: "Devin: api_key required" };
}
var extra = {};
try { extra = JSON.parse(ctx.extra); } catch (e) { extra = {}; }
if (extra == null || typeof extra !== "object") extra = {};
var nested = extra.devin != null && typeof extra.devin === "object" ? extra.devin : {};
var orgId = typeof nested.org_id === "string" ? nested.org_id : "";
if (orgId === "" && typeof extra.org_id === "string") orgId = extra.org_id;
orgId = orgId.trim();
if (orgId === "") {
  return { success: false, error: 'Devin: missing org_id in platform.extra (expected {"devin":{"org_id":"<id>"}})' };
}
var body;
try {
  body = http.get("https://api.devin.ai/v3/organizations/" + encodeURIComponent(orgId) + "/consumption/daily", { Authorization: "Bearer " + ctx.apiKey });
} catch (e) {
  return { success: false, error: httpErr(e) };
}
if (body == null) body = {};
var totalAcus = parseNum(body.total_acus);
if (totalAcus === null) {
  return { success: false, error: "Missing total_acus field" };
}
return {
  success: true,
  error: null,
  balance: {
    remaining: 0.0,
    total: null,
    used: totalAcus,
    currency: "ACU",
    is_valid: true
  },
  coding_plan: null
};
